/// <summary>
///  AVA
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormDataSourceEventHandler(formDataSourceStr(InterCompanyTradingRelationSetupCustomer, InterCompanyTradingPartnerVendor), FormDataSourceEventType::Activated)]
public static void InterCompanyTradingPartnerVendor_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    InterCompanyTradingPartner  ICTradingPartnerVend = sender.formRun().dataSource(formDataSourceStr(InterCompanyTradingRelationSetupCustomer,InterCompanyTradingPartnerVendor)).cursor();
    FormFunctionButtonControl   buttonICPriceTransfer =  sender.formrun().design().controlName(formcontrolstr(InterCompanyTradingRelationSetupCustomer, AVAICPriceTransfer)) ;

    buttonICPriceTransfer.enabled(ICTradingPartnerVend.VendorDataAreaId && ICTradingPartnerVend.VendorParty);
}

